def coinChange(coins, amount):
    INF = float('inf')
    dp = [0] + [INF] * amount
    for x in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= x and dp[x - c] + 1 < best:
                best = dp[x - c] + 1
        dp[x] = best
    return dp[amount] if dp[amount] != INF else -1

